            return self.calculate_cost() > other.calculate_cost()
        return NotImplemented

    def __le__(self, other: "DessertItem") -> bool:
        if isinstance(other, DessertItem):
            return self.calculate_cost() <= other.calculate_cost()
        return NotImplemented

    def __ge__(self, other: "DessertItem") -> bool:
        if isinstance(other, DessertItem):
            return self.calculate_cost() >= other.calculate_cost()
        return NotImplemented


class Candy(DessertItem):
