    print("m3:", m3)

    m4 = m1 * 2
    m5 = 3 * m2
    print("m4:", m4)
    print("m5:", m5)

    print(m1 == Money(2, 150))
    print(m1 == Money(3, 49))


if __name__ == "__main__":
    main()

