    def __str__(self) -> str:
        return (
            f"{self.name} ({self.packaging})\n"
            f"  {self.cookie_quantity} cookies @ ${self.price_per_dozen:.2f}/dz: ${self.calculate_cost():.2f} [Tax: ${self.calculate_tax():.2f}]"
        )


class IceCream(DessertItem):
