    def __init__(self, name: str = "", scoop_count: int = 0, price_per_scoop: float = 0.0) -> None:
        super().__init__(name, "Bowl")
        self.scoop_count = scoop_count
        self.price_per_scoop = price_per_scoop

    def calculate_cost(self) -> float:
